sp_widget.client_script:
api.controller = function($interval, $scope) {
   var c = this;

    c.isLoading = true;
    c.progress = 0;
    c.errorList = [];

    // Check what the server sends (simulate for now)
    var serverResponse = c.data || {};

    // Message flag
    c.noErrorsMessage = "";

    // Simulate data load (replace this with actual async call)
    setTimeout(function() {
        c.isLoading = false;

        // Case: Data was present; check for other errors
        c.errorList = Array.isArray(serverResponse.errorList) ? serverResponse.errorList : [];

        if (c.errorList.length === 0) {
            c.noErrorsMessage = "Validation Successful. No Errors found for the uploaded transaction references";
        } else {
            c.noErrorsMessage = "Validation completed with errors. Please check the details."; // Set message for errors as well
        }

        // Stop progress bar
        if (progressInterval) {
            $interval.cancel(progressInterval);
        }

        // Apply changes if needed
        if (!$scope.$$phase) $scope.$apply();

        // ****** NEW ADDITION: Send data back to the spModal.open().then() caller ******
        // Automatically close the modal and send data back once errorList is populated
        // and initial display is ready.
        // You might consider adding a slight delay here if the user needs to see the
        // loading state briefly before it closes, or control closing with buttons.
        $scope.close({
            status: 'dataLoaded', // Custom status indicating data is ready
            errorList: c.errorList, // The populated error list
            noErrors: c.errorList.length === 0, // Boolean flag for convenience
            message: c.noErrorsMessage // The final message
        });

    }, 3000); // simulate async delay

    // Progress bar logic
    c.progress = 0;
    var progressInterval = $interval(function() {
        if (c.progress < 100) {
            c.progress += 5;
        } else {
            c.progress = 0;
        }
    }, 200);

    // Optional: Keep this if you have explicit OK/Cancel buttons within the widget HTML
    // and you want them to trigger the close. If spModal handles its own buttons,
    // this function might not be called by them directly.
    c.closeModal = function(action) {
        $scope.close({
            status: action,
            errorList: c.errorList,
            noErrors: c.errorList.length === 0,
            message: c.noErrorsMessage
        });
    };
};

sp_widget.css:
/* HSBC Theme for Validation Errors Widget */

/* Overall Panel Styling */
.panel.panel-default {
    border-color: #DB0011; /* HSBC Red for the border */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); /* Subtle shadow for depth */
}

/* Panel Heading - Container for Logo, Title, and Spacer */
.panel-heading {
    background-color: #ffffff; /* HEADER BACKGROUND IS WHITE */
    border-color: #DB0011; /* Ensure border matches your theme */
    padding: 10px 20px; /* Adjust padding for white spacing around the logo and title area */

    /* Flexbox properties for layout */
    display: flex;
    align-items: center; /* Vertically center all items (logo, title, spacer) */
    justify-content: space-between; /* Distribute items with space between them */
}

/* HSBC Logo Styling (left aligned) */
.hsbc-logo-left {
    height: 35px; /* Adjust height for clear visibility of the SVG logo */
    width: auto; /* Maintain aspect ratio */
    flex-shrink: 0; /* Prevent logo from shrinking */
    margin-right: 15px; /* Add some space between logo and title */
    flex: 0 0 auto; /* Don't grow, don't shrink, base size on content */
}

/* Centered Title Styling */
.panel-title-centered {
    flex-grow: 1; /* ALLOW IT TO GROW to take available space */
    text-align: center; /* Center text within its own block */
    margin: 0; /* Reset margin to ensure text-align takes full effect within its flex container */

    font-weight: normal; /* No bold */
    font-size: 1.3em;
    text-transform: none; /* Display as "Validation Errors" (Title Case) */
    color: #333333; /* VALIDATION ERRORS TEXT IS BLACK */
    flex-shrink: 0; /* Prevent title from shrinking */
}

/* Spacer div to push the title to the center and logo to the left */
.header-spacer {
    flex-grow: 1; /* This makes the spacer take up all available space on the right */
}

/* Panel Body */
.panel-body {
    background-color: #ffffff; /* Clean white background */
    padding: 20px; /* Consistent padding */
}

/* Progress Bar Styling */
.progress {
    height: 25px; /* Slightly taller progress bar */
    background-color: #e0e0e0; /* Lighter grey for track */
    border-radius: 5px;
    box-shadow: none; /* Remove default bootstrap shadow if any */
}

.progress-bar {
    background-color: #DB0011; /* HSBC Red for the bar itself */
    font-weight: bold;
    line-height: 25px; /* Vertically center text */
    color: #ffffff; /* White text on bar */
}

/* Table Styling for Errors */
.table.table-bordered.table-striped {
    width: 100%;
    margin-bottom: 0;
    border-collapse: collapse; /* Ensure borders collapse for a clean look */
    border: 1px solid #e0e0e0; /* Main outer border for the table */
}

.table.table-bordered.table-striped thead {
    background-color: #DB0011; /* TABLE HEADER BACKGROUND IS HSBC RED */
    color: #ffffff; /* TABLE HEADER TEXT IS WHITE */
}

.table.table-bordered.table-striped th {
    border: 1px solid #e0e0e0; /* Border for header cells */
    border-bottom: 2px solid #DB0011; /* Stronger red line under header - kept for consistency */
    font-weight: bold;
    padding: 12px 15px;
    text-align: left;

    /* STICKY HEADER PROPERTIES - REFINED */
    position: sticky; /* Make the header sticky */
    top: 0; /* Stick it to the top of its scrolling container */
    z-index: 10; /* Ensure it stays above scrolling content */
    background-color: #DB0011; /* Re-apply background-color to ensure it's not transparent when sticky */
}

.table.table-bordered.table-striped tbody tr:nth-of-type(odd) {
    background-color: #fdfdfd; /* Very subtle off-white for odd rows */
}

.table.table-bordered.table-striped tbody tr:nth-of-type(even) {
    background-color: #ffffff; /* White for even rows */
}

.table.table-bordered.table-striped td {
    border: 1px solid #d0d0d0; /* REVISED: Slightly darker border for body cells */
    padding: 10px 15px;
}

/* Message When No Errors (Success/Empty File) */
.alert.alert-success {
    background-color: #e6ffe6; /* Very light green, almost white, for success */
    border-color: #4CAF50; /* Standard success green border */
    color: #333333; /* Dark grey text for readability */
    font-weight: bold;
    text-align: center;
    padding: 15px;
    border-radius: 5px;
    margin-bottom: 0;
}

/* CSS for the Vertical Scrollbar within the widget */
.table-scroll-container {
    max-height: 300px; /* Adjust this value as needed to control table height */
    overflow-y: auto;  /* Adds a vertical scrollbar when content exceeds max-height */
    border: 1px solid #e0e0e0; /* Border for the scrollable container itself */
    margin-top: 15px;
    margin-bottom: 15px;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.05);
    padding-right: 5px; /* Space for the scrollbar */
    position: relative; /* Essential for sticky to work correctly within this container */

    /* Custom Scrollbar Styling (for Webkit browsers like Chrome, Safari) */
    &::-webkit-scrollbar {
        width: 8px; /* Width of the vertical scrollbar */
    }

    &::-webkit-scrollbar-track {
        background: #f1f1f1; /* Color of the scrollbar track */
        border-radius: 10px;
    }

    &::-webkit-scrollbar-thumb {
        background: #DB0011; /* Color of the scrollbar thumb (HSBC Red) */
        border-radius: 10px;
    }

    &::-webkit-scrollbar-thumb:hover {
        background: #b3000f; /* Darker red on hover */
    }
}

sp_widget.script:
(function() {

    var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
    var getTempAttachment = new GlideRecord("sys_attachment");
    getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
    getTempAttachment.orderByDesc('sys_created_on');
    getTempAttachment.query();
    if (getTempAttachment.next()) {
        var attachmentSysId = getTempAttachment.table_sys_id;
        var tradeMarket = input.tradeMarket; //inputs from client script
        var errorList = new x_938076_now_utils.MSSCustodyBulkFileUpload().bulkLevelParse(attachmentSysId, tradeMarket);
        gs.info('Bulk Errors Widget ' + errorList);
        var finalArr = "[" + errorList + "]";
        data.errorList = JSON.parse(finalArr);
        gs.info('Bulk errors ' + data.errorList);
        console.log('Final Array ' + data.errorList);

    }


})();
